export const LYRIAN_BREAKTHROUGHS: readonly LyrianBreakthrough[] = [
  { name: "8 Eyes (Spiderfolk)", cost: 100, description: "You may have up to 8 Mystic Eyes instead of the regular 2." },
  { name: "Angelblooded (Human) (Restricted)", cost: 0, description: "You have the blood of angels in you. You may purchase the Angelblooded class." },
  { name: "Arachne (Spiderfolk)", cost: 0, description: "You lose your extra arms racial ability. In exchange, you become Large size and your max burden is increased by 2. When attempting to move through 5ft wide spaces, it is considered difficult terrain for you and many humanoid buildings will struggle to accommodate you. You also suffer a -10 penalty to swimming checks, but you may climb through your spider climb ability at your normal speed instead of half speed.\n\nIn addition, you count as mounted for the purposes of abilities that require you to be mounted. This does not let you be a mount to other creatures." },
  { name: "Become Fire (Salamander)", cost: 200, description: "The RP cost of Consume Fire is reduced to 0." },
  { name: "Become Ice (Yuki-Onna)", cost: 200, description: "The RP cost of Absorb Ice is reduced to 0 the first time you use it per round. Cost is reset back to 0 when it becomes your turn" },
  { name: "Become Lightning (Raijin)", cost: 200, description: "The RP cost of Consume Lightning is reduced to 0 the first time you use it per round. Cost is reset back to 0 when it becomes your turn. Any Power bonus you gain from using Consume Lightning does not stack." },
  { name: "Become Wind (Sylph)", cost: 200, description: "The RP cost of Consume Wind is reduced to 0 the first time you use it per round. Cost is reset back to 0 when it becomes your turn" },
  { name: "Blend In (Slimefolk)", cost: 200, description: "You disguise your appearance using magic to be that of another race (and gain a +30 bonus to hide this magical effect from things such as sense magic). This skill does not allow you to change your appearance at will, but instead lets you appear as you would as a different race.  You choose this race when this breakthrough is picked up and cannot change it.\n\nIn addition, the first time you use Slime Body while disguised in this way, it costs 0 RP instead of 1 RP but reveals your actual race.  This effect does not work if the attacker knows that you are a Slimefolk." },
  { name: "Blend In II (Slimefolk)", cost: 25, description: "You may disguise as a different race in addition to your chosen race during Blend In. You may take this breakthrough multiple times, selecting a new race to disguise as each time." },
  { name: "Blessed by Kari (Human)", cost: 100, description: "After using Divine Providence you may use it a second time before resting, but the cost increases to 1 RP. This second use must pick a different option then your first one." },
  { name: "Bully", cost: 50, description: "You gain a +5 bonus to intimidation skill checks against targets with less Fitness than you." },
  { name: "Celestial Dragon (Ryujin)", cost: 300, description: "Your elemental mastery from your Ryujin's Mastery may be Holy or Dark as well. In addition, you can use Flight." },
  { name: "Combat Doggy (Cu Sith)", cost: 100, description: "You may use abilities like normal while in Dog Form and may use One-Handed weapon. Any abilities that require a specific armor or other specific physical requirements still cannot be used.\n\nYour Dog Form no longer breaks upon taking damage." },
  { name: "Combat Kitty (Cait Sith)", cost: 100, description: "You may use abilities like normal while in cat form and may use One-Handed weapon. Any abilities that require a specific armor or other specific physical requirements still cannot be used.\n\nYour cat form no longer breaks on damage." },
  { name: "Curse of Vampirism", cost: 300, description: "You rise as a vampire, an immortal creature that feeds on the blood of living creatures and immediately gain the Vampire racial style class and its key ability. Your race changes to ‘Vampire’, but you keep the benefits of your previous race.\n\nAs a vampire, you no longer age and your physical appearance changes slightly. Your skin becomes more pale and you grow a pair of fangs. You still need to eat, drink and breathe as normal.\n\nA vampire’s spirit core is cracked, making it difficult for it to regenerate mana naturally and requiring it to obtain it from other creatures. You no longer regenerate mana from eating (including potions), resting and can no longer use the Draw Mana encounter conclusion action. You still recover full mana at the start of a new arc. \n\nYou are weak to sunlight. Every round you spend in sunlight without proper protection you take 10 true damage and your maximum HP is lowered by 10. Your maximum HP remains lowered until you finish a rest. You may carry a parasol or similar object in one hand to protect yourself from the sun and can do so even in combat.\n\nIn addition to these drawbacks, you no longer receive Wounds unless the damage that reduced your HP to 0 was fire, holy or true damage. You also gain 60ft Darkvision. Darkvision lets you see in total darkness, even if there's no source of light." },
  { name: "Deep Connection", cost: 50, description: "You may command your mount to move and attack even if you're not mounted on it. This still using AP, Mana etc like normal as if you were mounted." },
  { name: "Deus Ex Machina", cost: 600, description: "The first time you would die from a mortal wound at Encounter Conclusion, the mortal wound is removed and you instead receive a normal injury. The benefit of this breakthrough is then lost and you may not choose this breakthrough again after." },
  { name: "Divine Luck I", cost: 300, description: "Once per rest, you may roll an additional dice when making a check and take the higher result." },
  { name: "Divine Luck II", cost: 600, description: "Once per arc, you may choose to automatically succeed on a check (if success is possible)." },
  { name: "Divine's Chosen", cost: 0, description: "You select one of the divines from the below list to worship. Once chosen, you can only change this decision with GM approval after a significant enough change.\n\nAny abilities with the Divine keyword deal your chosen divine's damage instead of their listed type. \n\nKari: (Type Holy) goddess of Light, the most prominent deity in the setting, almost all religious people follow Kari and it's the only serious religion with any support outside of Kirara. \n\nHeira: (Type Astra) goddess of Evil, mostly followed by cultists. \n\nPandora: (Type Arcane) goddess of Magic (Arcane). There are a few broken-down shrines to her, not widely followed, but a few followers. \n\nMakai: (Type Water) goddess of the Ocean. Mostly followed in Houkaina and Kirara, moreso in Houkaina. Main temple is in Houkaina (in Northi), followed by Merfolk. \n\nAyuzi Kirara: (Type Fire) goddess of Artisans. The most popular Divine in Kirara. \n\nEisen: (Type Physical) god of War. Mostly followed by goblins and orcs in Eisenstadt. Mostly seen as ceremonial and \"old ways,\" not taken as seriously in Eisenstadt. \n\nAthena: (Type Lightning) goddess of Wind and Lightning. Mostly followed by citizens of the area around Marlone Bay. A goddess with a quiet disposition. Mostly the \"old ways,\" a sailor might make a gesture to Athena before setting out while not fully being a follower. \n\nClio: (Type Arcane) goddess of Storytelling. Not officially followed anywhere, or even known about. Clio draws power from all of the stories forged through life, both true and fictional. \n\nYggdrasil: (Type Earth) the world itself. Mostly followed by Fae in Easter. \"Nature,\" \"Terra itself\" are Yggdrasil. \"The will of the world/nature.\" Not actually a \"sentient\" force, but a force that creates balance and opposes destruction of natural order. Yggdrasil's strength is that it has four \"superpaladins\" (thaumaturges) that are bound to the world and cannot be permanently killed. The thaumaturges do not work together, and may not even be aware of each other, and may not even be aware of their mission." },
  { name: "Drag along (Lamia)", cost: 200, description: "When you have a target under the effect of \"Just a hug\", you can still move at half of your normal movement speed while under the Just a hug root effect and you still count as rooted for all other purposes.\n\nWhen moving, you can drag along the target of Just a hug, but they still count as rooted at your new location.\n\nIn addition, your grapple power increases by +1." },
  { name: "Dual Personality", cost: 300, description: "Whether through magical or non-magical means, you have more than a single personality or entity within you through either physical or magical means. When under the influence of a Charm, Illusion or other mind-influencing effect you may spend 1 AP to switch personalities/entities and act as normal.\n\nYou may only do this once per encounter." },
  { name: "Early Ascension", cost: 300, description: "You are treated as having 1 class mastered for the purposes of selecting a tier 2 class that has “Any class mastered” or similar requirement. This does not apply to any class that requires a specific class to be mastered and it doesn't automatically qualify you for other requirements such as weapon proficiencies." },
  { name: "Elemental Affinity", cost: 150, description: "You gain Elemental Mastery in an element of your choice.\n\nYou may pick this breakthrough more than once, choosing a different element each time." },
  { name: "Elemental Breath (Ryujin)", cost: 100, description: "You may let your Dragon Breath do the damage of any element that you have mastered." },
  { name: "Elixir Addict", cost: 0, description: "You have become used to the effects of drinking elixirs, too used in fact. At the end of your turn in combat, if you do not have an Elixir active you take 6 true damage. The HP cost of drinking all elixirs is reduced by 11.\n\nThis breakthrough may be removed during an interlude phase by spending 1 IP." },
  { name: "Expert Summoner", cost: 0, description: "When you summon during the first or second round of an encounter, you may transfer main stat points from yourself into your summon.\n\nThe maximum stat points you can imbue for all your summons combined is equal to your total main stat points (Focus, Power, Agility, Toughness) - 18. You can not lower a stat below 3 with this. When you lose stat points due to this, your related values such as mana, HP and RP have their max reduced. When lowering your agility or toughness, you also lose RP or HP equal to the respective stat lost. If your  Mana is higher than your max Mana after imbuing, it is reduced to the new max.\n\nThis transfer stays until end of encounter or until the summon you invested in dies (or is otherwise removed from combat). Your max of your stats is returned to normal, but any HP or Mana lost due to this is not refunded.\n\nYou may imbue a Heroic summon with any amount of stats from this pool. These points don't need to be a direct transfer (for example, you can lower your Agility by 2 to buff your summons Power). They increase your summons values such as HP/RP etc by the regular amount these stats give.\n\nFor grunt summons, you may imbue them with half of this max. They are still capped at max 1 RP." },
  { name: "Fae Flash Acrobat (Fae)", cost: 50, description: "While using Fae Flash, you may teleport a partial distance and materialize there to redirect your teleport. In a single Fae Step, you may teleport multiple times, reappearing each time you stop, to teleport from that new position. You are still limited by your maximum teleport distance and cannot take any other actions between each teleport." },
  { name: "Faerie Flash Master (Fae)", cost: 100, description: "When using your Faerie Flash ability, you may spend X additional mana to increase your teleport distance by X times your movement speed." },
  { name: "Faerie-Chimera Hybrid (Race)", cost: 200, description: "An extremely rare condition in which a Chimera parent and a Faerie parent produces a child with Chimera traits. The odds are said to be less than 1%.\n\nIf your main race is Chimera, you may choose a Fae subrace instead of a Chimera one. If your main race is Fae, you may choose a Chimera subrace instead of a Fae one. \n\nYou do not get any of the base traits from the other race and keep the ones from your chosen main race. However, you do get the language from the other race (or a dialect of choosing a chimera subrace)\n\nIf you pick High Fae as your subrace, you gain Fae Flash instead of Fae Flash II." },
  { name: "Fast Metabolism", cost: 150, description: "Once per arc you may eat food and gain the benefits even if you already had gotten the benefits from eating food that day." },
  { name: "Fast Movement (Centaur)", cost: 200, description: "Your base movement speed increases by 5ft." },
  { name: "Fearless", cost: 200, description: "Whenever you are afflicted by a Fear type condition, you may spend 1 RP or 0 AP to remove it." },
  { name: "Fight and Flight (Chimera)", cost: 200, description: "When using Fight or Flight, you no longer receive the drawback." },
  { name: "Flesheater (Jiangshi)", cost: 100, description: "When using Consume Enemy, you may consider that your food for the day and regain mana equal to a normal ration. You cannot gain this benefit if you already regained mana from food that day and using this benefit prevents you from regaining mana from food until you’ve rested." },
  { name: "Flying Counter (Kitsune)", cost: 200, description: "When using Fading Counter, you may move up to your movement speed instead of 5ft. This movement has Flight and still does not provoke attacks of opportunity." },
  { name: "Four Paw Sprint (Catfolk)", cost: 100, description: "When spending at least 3 AP of movement, your base movement speed is increased to 40ft instead of 25." },
  { name: "Greatshield Training", cost: 100, description: "You gain proficiency with Greatshields." },
  { name: "Heavy Armor Training", cost: 100, description: "You gain proficiency with Heavy Armor." },
  { name: "Hide Behind Ally (Pixie)", cost: 300, description: "When occupying the same space as a conscious ally that's at least a size bigger than you, you may choose to become untargetable to single target attacks. \n\nWhen targeted by a single target attack, you may direct the attack a willing ally with which you spare the space. They may react to this attack as normal. After you re-direct an attack like this once, you automatically redirect all other attacks you can until the start of your next turn\n\nWhile occupying the same space as a conscious ally, any effect that triggers upon not being targeted by an enemy (such as Challenge) will not be triggered. Does not work against Attacks of Opportunity." },
  { name: "Human-Chimera Hybrid (Race)", cost: 200, description: "While most unions of Human and Chimera parents result in the offspring being fully of Human or fully of Chimera, there are rare instances in which the Chimera traits are still present in a human offspring.\n\nChoose one Chimera Subrace and gain all of its features. You do not gain any of the Chimera base traits and instead have the Human ones, including Divine Providence. You do not get the 100 extra exp that humans normally get or human adaptability." },
  { name: "Improved Demonic Divine Release (Demon)", cost: 300, description: "When activating your divine release you may choose to reduce your max HP by 22. When you do, you do not pay any additional HP cost to activate it and the HP Upkeep is reduced to 0 while above 0 HP.\n\nWhen you fall below 0 HP, you pay the increased Upkeep cost as normal." },
  { name: "In Sync (Youkai)", cost: 100, description: "After you use Spiritual Sync, you may cancel the effect for 0 RP at any time. If you do, you regain mana like it is described in the ability or 8 HP for each temporary mana you still had remaining.\n\nIn addition, the maximum mana or HP you can spend on Spiritual Sync is doubled." },
  { name: "Kit Expert", cost: 200, description: "You may reduce the Burden cost of a single kit in your inventory by 2." },
  { name: "Language Training", cost: 100, description: "You learn a language of your choice. Rare, dead or similar languages may be unavailable (GM’s discretion).\n\nYou may take this breakthrough multiple times, picking a different language each time." },
  { name: "Large Specimen (Nio, Bullfolk or Bearfolk)", cost: 100, description: "Your size becomes Large." },
  { name: "Light Armor Training", cost: 25, description: "You gain proficiency with Light Armor and shields." },
  { name: "Light Sleeper", cost: 75, description: "When asleep, you may roll Perception rolls as if you were awake to be aware of danger approaching." },
  { name: "Mark of Conflict", cost: 0, description: "The effect of your Mark of Justice changes to the following:\n\n“You mark a single enemy, inflicting the Mark of Conflict on them. If an enemy moves away from you and not towards another ally, they take Full Pierce physical damage equal to your Power for each 20ft of movement they spent moving away from you.”\n\nThe range and AP cost remain the same." },
  { name: "Medium Armor Training", cost: 50, description: "You gain proficiency with Medium Armor." },
  { name: "Mental Torture (Unseelie)", cost: 100, description: "When you roll a natural 20 on your accuracy roll, you may apply the effects of Torture Techniques even if the enemy Dodges or Blocks it." },
  { name: "Mixed House (Demon)", cost: 100, description: "You choose another house to gain the benefit of." },
  { name: "Mystic Eyes of Faerie Light (Fae)", cost: 100, description: "Your Fae eyes have developed into the Eyes of Faerie Light.  You may purchase the Faerie Light Eyes class.\n\nIn addition, you can make a Perception check at +10 bonus to determine if something is an illusion. You are not immune to these illusions however." },
  { name: "Natural Immunity (Ratfolk)", cost: 100, description: "When you successfully resist the effect of a disease or poison (or are immune to the effect), you may choose to become afflicted anyway. You suffer no effects from a disease or poison you choose to accept this way. This poison or disease lasts the normal duration or until the end of the encounter, whichever is shorter." },
  { name: "On the draw", cost: 100, description: "You gain +1 to your initiative." },
  { name: "Organized Inventory", cost: 100, description: "Increases your in-combat burden capacity by 1." },
  { name: "Organized Inventory II", cost: 200, description: "Your in-combat Burden capacity is increased by 1." },
  { name: "Organized Inventory III", cost: 300, description: "Your in-combat Burden capacity is increased by 1." },
  { name: "Overrun (Centaur)", cost: 200, description: "When using the Charge or Spear Charge ability your movement speed is increased by 5ft and if your attack made through the Charge ability does damage, it knocks the target prone." },
  { name: "Panda Martial Arts (Red Panda)", cost: 100, description: "You can be in Panda stance at the same time as another stance without either stance ending.\n\nOther rules for stance breaking (such as entering 2 non-panda stances) still apply." },
  { name: "Photosynthesis (Dryad)", cost: 100, description: "By spending at least an hour in the direct sunlight, you may gain the benefits of having eaten food and you do not need to eat or drink for the next 24 hours." },
  { name: "Power Saving Mode (Ancient Marionette)", cost: 100, description: "If you are at maximum mana during your meal, you only need to consume half the normal amount to be well fed." },
  { name: "Powerful Ki (Oni)", cost: 200, description: "When using Gravitational Ki, the range increases by 30ft. The push and pull distance increases by up to 10ft. In addition, you may spend 1 AP instead of 1 RP on it." },
  { name: "Primary Stat Training", cost: 400, description: "You gain a +1 bonus to Focus, Power, Agility or Toughness.\n\nThis breakthrough can be selected multiple times. The effects stack. Each time you take this breakthrough the cost increases by 100, up to a maximum of 700." },
  { name: "Racial Flight", cost: 300, description: "You may use Flight." },
  { name: "Rapid Flash (High Fae)", cost: 100, description: "Your Fae Flash gains the Rapid keyword." },
  { name: "Rich Parents", cost: 300, description: "You start the game with an additional 3000 Clim of funds." },
  { name: "Secondary Stat Training", cost: 200, description: "You gain a +1 bonus to Fitness, Cunning, Reason, Awareness or Presence.\n\nThis breakthrough can be selected multiple times. The effects stack." },
  { name: "Skill Training", cost: 25, description: "You gain a single skill point or two expertise points to spend on a skill. Crafting skills cannot be selected with this training.\n\nYou may select this breakthrough multiple times. Its effects can stack." },
  { name: "Skilled Flier", cost: 100, description: "When you are about to lose Height from taking damage due to your Flight ability, you may instead spend 3 Mana to negate losing height from the flight mechanic until the start of your next turn.\n\nAbilities that make you lose height not part of the Flight ability (such as downburst) may still knock you out of the air." },
  { name: "Slime Summoner", cost: 100, description: "When using the Summon Animal ability, you may instead choose to summon slimes. You roll randomly from the following slimes: Slime, Fire Slime, Earth Slime, Water Slime, Wind Slime or Mana Slime.\n\nEven if you have the Wildheart class, you still cannot choose which slime you summon except you may choose to summon the regular Slime." },
  { name: "Slow Starter", cost: 300, description: "You receive 200 less EXP at character creation to spend on classes and abilities. Every time you get EXP after character creation, you get twice as much. This lasts until you’ve received a total of 500 (1000 when doubled) exp." },
  { name: "Small Doggy (Cu Sith)", cost: 0, description: "When you enter your Dog Form, you become a small dog instead. Instead of the usual bonuses and penalties, you instead lose 4 guard and 8 Block but gain a +2 Size bonus to Evasion and Dodge." },
  { name: "Small Specimen (Cowfolk)", cost: 25, description: "Your size is Small instead of Medium." },
  { name: "Speciality Weapon Training", cost: 100, description: "You gain proficiency with a Speciality Weapon group.\n\nThis breakthrough can be selected multiple times. You must select a different weapon group each time you select it." },
  { name: "Summon Contract: Fortuna, Lady Luck", cost: 0, description: "Appearance: Fortuna appears as a beautiful lady wearing clothing of the highest quality. Her clothes change each time she appears, but she always carries with her a parasol designed like a roulette wheel.\nDesires: Fortuna desires to see gambling. To have people bet their all on impossible odds.\nPact Cost: You can never naturally roll 20 again. Every 20 you roll is reduced to 19.\nAttunement Cost: None\nRe-Summon Cost: Roll a natural 20 (before the pact cost reduces it) on an attack or skill check with consequences for failure (GM’s decision).\n\nWhen you contract Fortuna, you are able to attune to it. While attuned, you gain access to the Draw Luck ability through your Channel Eidolon ability. You summon the Jack of Hearts for your Lesser Eidolon and Fortuna for your Eidolon (The stats for these are listed under monsters)." },
  { name: "Summon Contract: Ixilune, The Swarm", cost: 0, description: "Appearance: Hot bug lady.\nDesires: Ixilune desires to consume everything.\nPact Cost: You need to eat 1.5x as much food to be fed.\nAttunement Cost: None\nRe-Summon Cost: Must eat the flesh of a creature of the same (main) race.\n\nWhen you contract Ixilune, you are able to attune to it. While attuned, you gain access the Distracting Swarm ability through your Channel Eidolon ability. You summon the Devouring Swarm for your Lesser Eidolon and Ixilune for your Eidolon. (The stats for these are listed under monsters.)" },
  { name: "Summon Contract: Pipoltr, The Gardener", cost: 0, description: "Appearance: Pipoltr appears as a giant scarab beetle whose carapace glints with a metallic sheen like burnished bronze and emerald green.  His presence is both otherworldly and ancient, curved antennae sprout from his head that can detect the health of plants.  His compound eyes shine like brilliant gems.Desires: Pipoltr’s desire is the health of nature.Pact Cost:  1 Maximum Mana.Attunement Cost: NoneRe-Summon Eidolon:  Character must spend an EP to perform 1 day of gardening work before resummoning Pipoltr.When you contract Pipoltr, you are able to attune to it. While attuned, you gain access the Vine Wall Cover ability through your Channel Eidolon ability. You summon the Rhinoceros Beetle for your Lesser Eidolon and Pipoltr for your Eidolon. (The stats for these are listed under monsters.)" },
  { name: "Superior Escapist (Rabbitfolk)", cost: 100, description: "You may use your Escape Artist when Rooted to remove it in addition to grapples." },
  { name: "Tengu Defensive Aura (Tengu)", cost: 100, description: "Your resistance to astra corruption is increased by 1 (Your SC is treated as 500 higher when determining if you suffer from astra corruption). In addition, you do not suffer any negative effects when the astra level is raised artificially. (such as from Exousiai's)." },
  { name: "The Unknown Paladin", cost: 200, description: "Despite not being human, you fulfill the human requirement to become a Paladin. In addition, your Smite skill's damage type changes to one that represents your chosen Divine. The paladin holy weapon key ability also changes its damage type to the one that represents your chosen Divine.\n\nKari: Holy \nHeira: Astra\nPandora: Arcane\nMakai: Water\nAyuzi Kirara: Fire \nEisen: Physical \nAthena: Lightning \nClio: Arcane \nYggdrasil: Earth" },
  { name: "Third Eye", cost: 200, description: "You may have up to 3 Mystic Eyes instead of the regular 2." },
  { name: "Touched by Death", cost: 200, description: "Near-death experiences sometimes leave people more sensitive to death itself, manifesting in what is called the Shinigami’s Eyes. You may purchase the Shinigami Eyes class.\n\nIn addition, you may spend 1 AP to see the HP percentage and weak spots (if any) of all creatures for 1 turn." },
  { name: "Universal Training", cost: 700, description: "You gain +1 to any primary stat, +1 to any secondary stat and 5 skill points. You may put these skill points into any normal skill, except crafting and gathering skills.\n\nThis breakthrough may be taken multiple times. The effects stack." },
  { name: "Weapon Training", cost: 25, description: "You gain proficiency with a weapon group. You may not select Speciality Weapons with this.\n\nThis breakthrough can be selected multiple times. You must select a different weapon group each time you select it." },
  { name: "Wide Circuits I", cost: 150, description: "Your maximum mana increases by 1." },
  { name: "Wide Circuits II", cost: 175, description: "Your maximum Mana is increased by 1." },
  { name: "Wide Circuits III", cost: 200, description: "Your maximum Mana is increased by 1." },
  { name: "Wide Circuits IV", cost: 250, description: "Your maximum Mana is increased by 1.\n\nYou may take this breakthrough multiple times. The effects stack." },
];
